use crate::output::Output;
use crate::parse::Properties;
use crate::CHUNK;

const HEAD: &str = "\
// \x40generated by ../generate. To regenerate, run the following in the repo root:
//
// $ curl -LO https://www.unicode.org/Public/18.0.0/ucd/UCD.zip
// $ unzip UCD.zip -d UCD
// $ cargo run --manifest-path generate/Cargo.toml

#[repr(C, align(8))]
pub(crate) struct Align8<T>(pub(crate) T);
#[repr(C, align(64))]
pub(crate) struct Align64<T>(pub(crate) T);
";

pub fn output(
    properties: &Properties,
    zero_start: usize,
    zero_continue: usize,
    trie_start: &[u8],
    trie_continue: &[u8],
    leaf: &[u8],
) -> Output {
    let mut out = Output::new();
    writeln!(out, "{}", HEAD);

    writeln!(
        out,
        "pub const UNICODE_VERSION: (u8, u8, u8) = {:?};",
        properties.unicode_version(),
    );
    writeln!(out);

    let ascii_start = (0u8..128)
        .map(|c| (properties.is_xid_start(c as char) as u128) << c)
        .sum::<u128>();
    writeln!(
        out,
        "pub(crate) const ASCII_START: u128 = 0x{ascii_start:x};",
    );

    let ascii_continue = (0u8..128)
        .map(|c| (properties.is_xid_continue(c as char) as u128) << c)
        .sum::<u128>();
    writeln!(
        out,
        "pub(crate) const ASCII_CONTINUE: u128 = 0x{ascii_continue:x};",
    );

    writeln!(out);

    writeln!(out, "pub(crate) const CHUNK: usize = {};", CHUNK);
    writeln!(out);

    writeln!(out, "// Positions of entries for the all-zero chunk.");
    writeln!(out, "pub(crate) const ZERO_START: usize = {zero_start};");
    writeln!(
        out,
        "pub(crate) const ZERO_CONTINUE: usize = {zero_continue};"
    );
    writeln!(out);

    writeln!(
        out,
        "pub(crate) static TRIE_START: Align8<[u8; {}]> = Align8([",
        trie_start.len(),
    );
    for line in trie_start.chunks(16) {
        write!(out, "   ");
        for byte in line {
            write!(out, " 0x{:02X},", byte);
        }
        writeln!(out);
    }
    writeln!(out, "]);");
    writeln!(out);

    writeln!(
        out,
        "pub(crate) static TRIE_CONTINUE: Align8<[u8; {}]> = Align8([",
        trie_continue.len(),
    );
    for line in trie_continue.chunks(16) {
        write!(out, "   ");
        for byte in line {
            write!(out, " 0x{:02X},", byte);
        }
        writeln!(out);
    }
    writeln!(out, "]);");
    writeln!(out);

    writeln!(
        out,
        "pub(crate) static LEAF: Align64<[u8; {}]> = Align64([",
        leaf.len(),
    );
    for line in leaf.chunks(16) {
        write!(out, "   ");
        for byte in line {
            write!(out, " 0x{:02X},", byte);
        }
        writeln!(out);
    }
    writeln!(out, "]);");

    out
}
